css:
.ss-social{display:flex;align-items:center;gap:14px;margin:0;padding:0;list-style:none}
.ss-social__i{display:flex}
.ss-social__a{display:flex;line-height:1}
.ss-social__a img{width:14px;height:14px;display:block}
.ss-social--light .ss-social__a img{filter:brightness(0) invert(1)}
.ss-social--dark .ss-social__a img{filter:none}
.ss-social__a:hover{opacity:.75}
/* Labelled variant: the handoff's official-channel pills — icon, name and a
   hairline box, on a card rather than on the dark chrome. */
.ss-social--pills{flex-wrap:wrap;gap:12px}
.ss-social--pills .ss-social__a{align-items:center;gap:8px;border:1px solid var(--line);padding:10px 16px;font:700 14px/1 var(--font-body);color:var(--ink)}
.ss-social--pills .ss-social__a:hover{opacity:1;background:var(--paper)}
.ss-social--pills.ss-social--light .ss-social__a{border-color:rgba(255,255,255,.35);color:#fff}
@media (max-width:640px){.ss-social{gap:4px}
.ss-social__a{min-width:44px;min-height:44px;align-items:center;justify-content:center}
.ss-social--pills .ss-social__a{min-width:0;padding:13px 16px}}
